268	    /**
269	     * Populate the owner's household size: the number of owners sharing this owner's
270	     * {@code householdId} (including the owner itself). An owner with no household is a household
271	     * of one. This value drives the {@code GOLD} membership tier (a household of three or more).
272	     *
273	     * @param owner the owner whose household size should be computed and set
274	     */
275	    private void populateHouseholdSize(Owner owner) {
276	        String householdId = owner.getHouseholdId();
277	        if (!StringUtils.hasText(householdId)) {
278	            owner.setHouseholdSize(1);
279	            return;
280	        }
281	        int size = (int) this.clinicService.findAllOwners().stream()
282	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
283	            .count();
284	        owner.setHouseholdSize(size);
285	    }
286	
287	    /**
288	     * Generate a customer code formatted {@code <CITY3>-<LAST3>-<NNNN>}, where {@code CITY3} is the
289	     * upper-cased first three letters of {@code city}, {@code LAST3} is the upper-cased first three
290	     * letters of {@code lastName} and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to
291	     * one more than the current number of owners already in that city (e.g. {@code SYD-SMI-0007}).
292	     *
293	     * @param city     the owner's city
294	     * @param lastName the owner's last name
295	     * @return the generated customer code
296	     */
297	    private String generateCustomerCode(String city, String lastName) {
298	        String cityPrefix = city.length() >= 3 ? city.substring(0, 3) : city;
299	        String lastPrefix = lastName.length() >= 3 ? lastName.substring(0, 3) : lastName;
300	        String normalizedCity = normalizeForComparison(city);
301	        int sequence = (int) this.clinicService.findAllOwners().stream()
302	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
303	            .count() + 1;
304	        return String.format("%s-%s-%04d", cityPrefix.toUpperCase(Locale.ROOT),
305	            lastPrefix.toUpperCase(Locale.ROOT), sequence);
306	    }
307	
308	    /**
309	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
310	     * following Monday, while a weekday is returned unchanged. This is the effective registration date
311	     * that is stored, returned and used for every value derived from it.
312	     *
313	     * @param date the effective registration date (supplied or defaulted)
314	     * @return the same date when it is a weekday, otherwise the next Monday
315	     */
316	    private LocalDate rollToBusinessDay(LocalDate date) {
317	        DayOfWeek dayOfWeek = date.getDayOfWeek();
318	        if (dayOfWeek == DayOfWeek.SATURDAY) {
319	            return date.plusDays(2);
320	        }
321	        if (dayOfWeek == DayOfWeek.SUNDAY) {
322	            return date.plusDays(1);
323	        }
324	        return date;
325	    }
