329	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
330	     *
331	     * @param customerCode     the owner's already-assigned customer code
332	     * @param registrationDate the owner's registration date
333	     * @return the generated membership number
334	     */
335	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
336	        String yy = String.format("%02d", registrationDate.getYear() % 100);
337	        return String.format("%s-M%s", customerCode, yy);
338	    }
